package gemini

import (
	"math"
	"regexp"
	"strconv"
	"strings"

	"github.com/easel/fizeau/internal/harnesses"
)

// Gemini CLI's /model manage TUI surfaces per-tier usage as rows such as:
//
//	Flash                  4% used      Resets 9:13 PM (23h 46m)
//	Flash Lite             0% used      Resets 9:27 PM (24h)
//	Pro                    100% used
//
// Names are version-sensitive; parse_gemini_model_manage accepts a small set
// of known tier labels and tolerates surrounding decoration (box-drawing
// glyphs, leading bullets, status badges).

var geminiAnsiPattern = regexp.MustCompile(`\x1b(?:\[[0-9;?]*[a-zA-Z]|[^[])`)

func stripGeminiANSI(s string) string {
	return geminiAnsiPattern.ReplaceAllString(s, "")
}

var (
	geminiUsedPercentPattern = regexp.MustCompile(`(\d+(?:\.\d+)?)\s*%\s*used`)
	geminiResetPattern       = regexp.MustCompile(`(?i)reset[s]?\s+(.*)`)
)

// geminiTier represents a tier surfaced in the /model manage dialog.
type geminiTier struct {
	// Label is the tier label expected in the Gemini CLI UI (case-insensitive).
	Label string
	// LimitID is the stable identifier persisted into cassettes and caches.
	// Downstream consumers compare LimitIDs, not labels.
	LimitID string
	// DefaultModel is the concrete model ID mapped to this tier.
	DefaultModel string
}

var geminiTiers = []geminiTier{
	{Label: "Pro", LimitID: "gemini-pro", DefaultModel: "gemini-2.5-pro"},
	{Label: "Flash Lite", LimitID: "gemini-flash-lite", DefaultModel: "gemini-2.5-flash-lite"},
	{Label: "Flash", LimitID: "gemini-flash", DefaultModel: "gemini-2.5-flash"},
}

// ParseGeminiModelManage parses the raw text captured from `gemini` in
// /model manage. It returns one QuotaWindow per recognised tier, with the
// tier label, used percent, reset text, and a derived quota state. Tiers
// missing in the captured text are simply absent from the returned slice.
func ParseGeminiModelManage(text string) []harnesses.QuotaWindow {
	text = stripGeminiANSI(strings.ReplaceAll(text, "\r\n", "\n"))
	lines := strings.Split(text, "\n")

	windows := make([]harnesses.QuotaWindow, 0, len(geminiTiers))
	seen := map[string]bool{}

	for i := 0; i < len(lines); i++ {
		line := lines[i]
		tier := tierForLine(line)
		if tier == nil {
			continue
		}
		if seen[tier.LimitID] {
			continue
		}
		// Look at the current line and up to two following lines for the
		// "% used" token and (optionally) a "Resets ..." fragment.
		usedPct, hasUsed, resetText := harvestTierEvidence(lines, i)
		if !hasUsed {
			continue
		}
		seen[tier.LimitID] = true
		windows = append(windows, harnesses.QuotaWindow{
			Name:        tier.Label,
			LimitID:     tier.LimitID,
			UsedPercent: usedPct,
			ResetsAt:    resetText,
			State:       geminiQuotaState(usedPct),
		})
	}
	return windows
}

func tierForLine(line string) *geminiTier {
	lower := strings.ToLower(line)
	// Match longer labels first so "Flash Lite" is never matched as "Flash".
	for i := range geminiTiers {
		if containsTierLabel(lower, strings.ToLower(geminiTiers[i].Label)) {
			return &geminiTiers[i]
		}
	}
	return nil
}

// containsTierLabel checks that the lowercase tier label appears in the line
// with word-like boundaries so "flashback" never matches "flash".
func containsTierLabel(lowerLine, lowerLabel string) bool {
	idx := strings.Index(lowerLine, lowerLabel)
	if idx < 0 {
		return false
	}
	if idx > 0 {
		prev := lowerLine[idx-1]
		if isTierLabelRune(prev) {
			return false
		}
	}
	end := idx + len(lowerLabel)
	if end < len(lowerLine) {
		next := lowerLine[end]
		if isTierLabelRune(next) {
			return false
		}
	}
	return true
}

func isTierLabelRune(b byte) bool {
	return (b >= 'a' && b <= 'z') || (b >= '0' && b <= '9')
}

func harvestTierEvidence(lines []string, start int) (float64, bool, string) {
	var usedPct float64
	var hasUsed bool
	var resetText string
	end := start + 3
	if end > len(lines) {
		end = len(lines)
	}
	for j := start; j < end; j++ {
		frag := lines[j]
		if !hasUsed {
			if m := geminiUsedPercentPattern.FindStringSubmatch(frag); m != nil {
				if pct, err := strconv.ParseFloat(m[1], 64); err == nil {
					usedPct = pct
					hasUsed = true
				}
			}
		}
		if resetText == "" {
			if m := geminiResetPattern.FindStringSubmatch(frag); m != nil {
				resetText = strings.TrimSpace(m[1])
			}
		}
		if hasUsed && resetText != "" {
			break
		}
	}
	return usedPct, hasUsed, resetText
}

// geminiQuotaState mirrors harnesses.QuotaStateFromUsedPercent but treats
// exhausted tiers (>=100% used) as an explicit "exhausted" state so downstream
// routing can distinguish a fully blown tier from merely approaching the cap.
func geminiQuotaState(used float64) string {
	rounded := int(math.Ceil(used))
	if rounded >= 100 {
		return "exhausted"
	}
	if rounded >= 95 {
		return "blocked"
	}
	return "ok"
}

// FindGeminiQuotaWindow returns the QuotaWindow matching limitID, or nil.
func FindGeminiQuotaWindow(windows []harnesses.QuotaWindow, limitID string) *harnesses.QuotaWindow {
	for i := range windows {
		if windows[i].LimitID == limitID {
			return &windows[i]
		}
	}
	return nil
}

// TierLimitIDForModel returns the tier limit_id that covers the given concrete
// Gemini model ID (e.g. "gemini-2.5-pro" -> "gemini-pro"). Unknown models
// return ("", false).
func TierLimitIDForModel(model string) (string, bool) {
	normalized := strings.ToLower(strings.TrimSpace(model))
	if normalized == "" {
		return "", false
	}
	// Match the more specific label first (flash-lite before flash).
	if strings.Contains(normalized, "flash-lite") || strings.Contains(normalized, "flash lite") {
		return "gemini-flash-lite", true
	}
	if strings.Contains(normalized, "pro") {
		return "gemini-pro", true
	}
	if strings.Contains(normalized, "flash") {
		return "gemini-flash", true
	}
	return "", false
}

// Package session owns direct PTY process lifecycle and timed raw/input events.
//
// See internal/pty/doc.go for the governing ADR/SPIKE citations that authorize
// this package boundary.
package session

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"
)

// Size is a terminal rows/columns pair.
type Size struct {
	Rows uint16
	Cols uint16
}

// OutputChunk is one timed raw PTY read.
type OutputChunk struct {
	Seq       uint64
	At        time.Time
	TMS       int64
	Offset    int64
	Bytes     []byte
	ReadError error
	EOF       bool
}

// EventKind identifies cassette-facing session events.
type EventKind string

const (
	EventOutput EventKind = "output"
	EventInput  EventKind = "input"
	EventResize EventKind = "resize"
	EventSignal EventKind = "signal"
	EventExit   EventKind = "exit"
)

// Event is the narrow timed event shape consumed by follow-on cassette code.
type Event struct {
	Seq    uint64
	Kind   EventKind
	At     time.Time
	TMS    int64
	Offset int64
	Bytes  []byte
	Key    Key
	Size   Size
	Signal string
	Exit   *ExitStatus
	Err    error
}

// Key names common terminal inputs.
type Key string

const (
	KeyEnter     Key = "enter"
	KeyTab       Key = "tab"
	KeyEscape    Key = "escape"
	KeyBackspace Key = "backspace"
	KeyUp        Key = "up"
	KeyDown      Key = "down"
	KeyRight     Key = "right"
	KeyLeft      Key = "left"
)

// CtrlKey returns a letter control-key input such as Ctrl-C.
func CtrlKey(r rune) Key {
	if r >= 'A' && r <= 'Z' {
		r += 'a' - 'A'
	}
	return Key(fmt.Sprintf("ctrl-%c", r))
}

// KeyBytes encodes a supported key as terminal input bytes.
func KeyBytes(k Key) ([]byte, error) {
	switch k {
	case KeyEnter:
		return []byte{'\r'}, nil
	case KeyTab:
		return []byte{'\t'}, nil
	case KeyEscape:
		return []byte{0x1b}, nil
	case KeyBackspace:
		return []byte{0x7f}, nil
	case KeyUp:
		return []byte("\x1b[A"), nil
	case KeyDown:
		return []byte("\x1b[B"), nil
	case KeyRight:
		return []byte("\x1b[C"), nil
	case KeyLeft:
		return []byte("\x1b[D"), nil
	}
	var r rune
	if _, err := fmt.Sscanf(string(k), "ctrl-%c", &r); err == nil {
		if r >= 'A' && r <= 'Z' {
			r += 'a' - 'A'
		}
		if r >= 'a' && r <= 'z' {
			return []byte{byte(r - 'a' + 1)}, nil
		}
	}
	return nil, fmt.Errorf("unsupported key %q", k)
}

// Clock lets tests inject deterministic timestamps.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Option configures Start.
type Option func(*Config)

// Config controls session startup.
type Config struct {
	Clock      Clock
	Timeout    time.Duration
	BufferSize int
}

// WithClock injects a deterministic clock.
func WithClock(clock Clock) Option {
	return func(cfg *Config) {
		cfg.Clock = clock
	}
}

// WithTimeout applies a wall-clock timeout in addition to ctx cancellation.
func WithTimeout(timeout time.Duration) Option {
	return func(cfg *Config) {
		cfg.Timeout = timeout
	}
}

// WithBufferSize changes the raw read buffer size.
func WithBufferSize(size int) Option {
	return func(cfg *Config) {
		cfg.BufferSize = size
	}
}

func applyOptions(opts []Option) Config {
	cfg := Config{Clock: realClock{}, BufferSize: 32 * 1024}
	for _, opt := range opts {
		opt(&cfg)
	}
	if cfg.Clock == nil {
		cfg.Clock = realClock{}
	}
	if cfg.BufferSize <= 0 {
		cfg.BufferSize = 32 * 1024
	}
	return cfg
}

// ExitStatus describes process termination.
type ExitStatus struct {
	Code     int
	Signal   string
	Exited   bool
	Signaled bool
	Err      error
}

// Session is a running PTY-backed process.
type Session struct {
	start  time.Time
	clock  Clock
	size   Size
	cancel context.CancelFunc

	mu       sync.Mutex
	seq      uint64
	offset   int64
	closed   bool
	waitOnce sync.Once
	waitDone chan struct{}
	waitStat ExitStatus
	readDone chan struct{}

	output       chan OutputChunk
	events       chan Event
	eventsMu     sync.Mutex
	eventsClosed bool

	impl sessionImpl
}

type sessionImpl interface {
	write([]byte) (int, error)
	resize(Size) error
	close() error
	kill() error
	wait() ExitStatus
}

var (
	// ErrClosed is returned when writing to a closed session.
	ErrClosed = errors.New("pty session closed")
)

// Output returns timed raw PTY chunks. The channel closes after the read loop
// reaches EOF or Close/Kill tears the PTY down.
func (s *Session) Output() <-chan OutputChunk { return s.output }

// Events returns timed input/output/resize/signal/exit events.
func (s *Session) Events() <-chan Event { return s.events }

// Size returns the last requested terminal size.
func (s *Session) Size() Size {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.size
}

// SendBytes writes literal bytes to the PTY and records an input event.
func (s *Session) SendBytes(b []byte) error {
	if len(b) == 0 {
		return nil
	}
	if err := s.ensureOpen(); err != nil {
		return err
	}
	if _, err := s.impl.write(b); err != nil {
		return err
	}
	s.emit(Event{Kind: EventInput, Bytes: append([]byte(nil), b...)})
	return nil
}

// SendKey writes a named key sequence to the PTY and records an input event.
func (s *Session) SendKey(k Key) error {
	b, err := KeyBytes(k)
	if err != nil {
		return err
	}
	if err := s.ensureOpen(); err != nil {
		return err
	}
	if _, err := s.impl.write(b); err != nil {
		return err
	}
	s.emit(Event{Kind: EventInput, Bytes: b, Key: k})
	return nil
}

// Resize changes the PTY size and records a resize event.
func (s *Session) Resize(size Size) error {
	if err := validateSize(size); err != nil {
		return err

---
		return err
	}
	if err := s.ensureOpen(); err != nil {
		return err
	}
	if err := s.impl.resize(size); err != nil {
		return err
	}
	s.mu.Lock()
	s.size = size
	s.mu.Unlock()
	s.emit(Event{Kind: EventResize, Size: size})
	return nil
}

// Close cancels the session context and closes the PTY file descriptor.
func (s *Session) Close() error {
	s.mu.Lock()
	already := s.closed
	s.closed = true
	s.mu.Unlock()
	if already {
		return nil
	}
	if s.cancel != nil {
		s.cancel()
	}
	return s.impl.close()
}

// Kill terminates the process group where supported and records a signal event.
// If the process exits naturally at the same time, the signal event is best
// effort and may race with the exit event.
func (s *Session) Kill() error {
	s.mu.Lock()
	already := s.closed
	s.closed = true
	s.mu.Unlock()
	if already {
		return nil
	}
	if s.cancel != nil {
		s.cancel()
	}
	s.emit(Event{Kind: EventSignal, Signal: "kill"})
	return s.impl.kill()
}

// Wait blocks until the process exits and returns its exit status.
func (s *Session) Wait() ExitStatus {
	s.waitOnce.Do(func() {
		s.waitStat = s.impl.wait()
		s.mu.Lock()
		s.closed = true
		s.mu.Unlock()
		s.emit(Event{Kind: EventExit, Exit: &s.waitStat})
		close(s.waitDone)
		if s.cancel != nil {
			s.cancel()
		}
	})
	<-s.waitDone
	return s.waitStat
}

func (s *Session) ensureOpen() error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		return ErrClosed
	}
	return nil
}

func (s *Session) emit(ev Event) Event {
	s.mu.Lock()
	s.seq++
	ev.Seq = s.seq
	ev.At = s.clock.Now()
	ev.TMS = ev.At.Sub(s.start).Milliseconds()
